<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ArrowDownToLine, CircleDollarSign, CreditCard, ReceiptText, Wallet } from 'lucide-vue-next'
import { api } from '../api'
import { useSessionStore } from '../stores/session'
import { useRoute } from 'vue-router'
const session=useSessionStore()
const route=useRoute()
const invoices=ref<any[]>([])
const payments=ref<any[]>([])
const loading=ref(true)
const error=ref('')
const checkoutNotice=ref('')
const paying=ref<string|null>(null)
const amount=ref<Record<string,string>>({})
const method=ref<Record<string,string>>({})
const isTenant=computed(()=>['BUYER','TENANT'].includes(session.session?.user.role||''))
const canManage=computed(()=>['ADMIN','OWNER','AGENT'].includes(session.session?.user.role||''))
const dueTotal=computed(()=>invoices.value.filter(x=>['DUE','PARTIAL','OVERDUE'].includes(x.status)).reduce((s,x)=>s+Number(x.amount)-Number(x.amountPaid),0))
async function load(){loading.value=true;try{const [i,p]=await Promise.all([api.get('/rent-invoices'),api.get('/payments')]);invoices.value=i.data;payments.value=p.data}catch(e:any){error.value=e.response?.data?.message||'Could not load rent ledger.'}finally{loading.value=false}}
async function pay(invoice:any){error.value='';paying.value=invoice.id;try{await api.post(`/rent-invoices/${invoice.id}/payments`,{amount:Number(amount.value[invoice.id]||Number(invoice.amount)-Number(invoice.amountPaid)),method:method.value[invoice.id]||'BANK_TRANSFER'});await load()}catch(e:any){error.value=e.response?.data?.message||'Could not record payment.'}finally{paying.value=null}}
async function checkout(invoice:any){error.value='';paying.value=invoice.id;try{const response=await api.post(`/rent-invoices/${invoice.id}/checkout`,{amount:Number(amount.value[invoice.id]||Number(invoice.amount)-Number(invoice.amountPaid))});window.location.assign(response.data.checkoutUrl)}catch(e:any){error.value=e.response?.data?.message||'Could not start online checkout.';paying.value=null}}
async function loadCheckoutStatus(){const tracker=route.query.tracker;if(typeof tracker!=='string')return;try{for(let attempt=0;attempt<6;attempt++){const status=(await api.get(`/rent-invoices/checkout/${encodeURIComponent(tracker)}`)).data;if(status.status==='SUCCEEDED'){checkoutNotice.value='Payment confirmed. Your rent ledger has been updated.';await load();return}if(status.status==='FAILED'||status.status==='CANCELLED'){checkoutNotice.value='That checkout did not complete. You can retry from the invoice.';return}if(attempt<5)await new Promise(resolve=>setTimeout(resolve,2000))}checkoutNotice.value='Payment confirmation is still pending from the provider. Refresh the ledger shortly.'}catch{checkoutNotice.value='Could not confirm that checkout. Refresh the rent ledger shortly.'}}
async function cancelReturnedCheckout(){const tracker=route.query.tracker;if(typeof tracker==='string')try{await api.post(`/rent-invoices/checkout/${encodeURIComponent(tracker)}/cancel`)}catch{/* The provider may have already confirmed or expired this checkout. */}}
const money=(n:any)=>`PKR ${Number(n).toLocaleString()}`
onMounted(async()=>{await load();if(route.query.checkout==='cancelled'){await cancelReturnedCheckout();checkoutNotice.value='Checkout was cancelled. The invoice balance is unchanged.'}else if(route.query.checkout==='return')await loadCheckoutStatus()})
</script>

<template><section class="workspace-content"><div class="section-toolbar"><div><h2>Rent ledger</h2><p>Track due dates, open balances, receipts, and collected rent.</p></div><span class="count-pill">{{money(dueTotal)}} outstanding</span></div><div v-if="error" class="notice error-notice">{{error}}</div><div v-if="checkoutNotice" class="notice">{{checkoutNotice}}</div><div class="rent-summary"><article><span class="kpi-icon gold"><ReceiptText/></span><small>Scheduled invoices</small><b>{{invoices.length}}</b></article><article><span class="kpi-icon orange"><CircleDollarSign/></span><small>Open balance</small><b class="money-kpi">{{money(dueTotal)}}</b></article><article><span class="kpi-icon green"><Wallet/></span><small>Recorded payments</small><b>{{payments.length}}</b></article></div><div v-if="loading" class="loading-row">Loading rent ledger…</div><div v-else-if="!invoices.length" class="empty-state compact-empty"><h3>No rent invoices yet</h3><p>Rent schedules appear when a property owner approves an application and creates a lease.</p><RouterLink v-if="isTenant" class="button button-outline" to="/workspace/deals">View rental listings</RouterLink></div><template v-else><div class="table-scroll panel-card"><table class="data-table"><thead><tr><th>PROPERTY / TENANT</th><th>RENT PERIOD</th><th>DUE DATE</th><th>AMOUNT</th><th>PAID</th><th>BALANCE</th><th>STATUS</th><th v-if="isTenant||canManage">ACTIONS</th></tr></thead><tbody><tr v-for="invoice in invoices" :key="invoice.id"><td><b>{{invoice.lease.property.title}}</b><small class="table-subline">{{isTenant?'Tenant account':invoice.lease.tenant.name}}</small></td><td>{{new Date(invoice.periodStart).toLocaleDateString([], {month:'short',year:'numeric'})}}</td><td>{{new Date(invoice.dueDate).toLocaleDateString()}}</td><td>{{money(invoice.amount)}}</td><td>{{money(invoice.amountPaid)}}</td><td><b>{{money(Number(invoice.amount)-Number(invoice.amountPaid))}}</b></td><td><span class="status-pill" :class="invoice.status.toLowerCase()">{{invoice.status}}</span></td><td v-if="isTenant||canManage"><span v-if="invoice.status==='CANCELLED'" class="muted">Cancelled</span><button v-else-if="isTenant&&Number(invoice.amount)>Number(invoice.amountPaid)" class="button button-outline" :disabled="paying===invoice.id" @click="checkout(invoice)"><CreditCard :size="14"/>Pay online</button><form v-else-if="canManage&&Number(invoice.amount)>Number(invoice.amountPaid)" class="inline-pay" @submit.prevent="pay(invoice)"><input v-model="amount[invoice.id]" type="number" min="1" :max="Number(invoice.amount)-Number(invoice.amountPaid)" :placeholder="String(Number(invoice.amount)-Number(invoice.amountPaid))"/><select v-model="method[invoice.id]" aria-label="Payment method"><option value="BANK_TRANSFER">Transfer</option><option value="CHEQUE">Cheque</option><option value="CASH">Cash</option></select><button class="button button-primary" :disabled="paying===invoice.id" type="submit">Record</button></form><span v-else class="paid-mark">Paid in full</span></td></tr></tbody></table></div><div class="payment-history"><div class="section-toolbar"><div><h2>Payment history</h2><p>Every recorded payment has a unique receipt reference.</p></div><ArrowDownToLine :size="18" class="muted"/></div><div v-if="payments.length" class="payment-list"><article v-for="p in payments" :key="p.id"><span class="payment-mark"><CreditCard/></span><span><b>{{p.invoice.lease.property.title}}</b><small>{{new Date(p.paidAt).toLocaleString()}} · {{p.method.replace('_',' ')}} · {{p.reference}}</small></span><strong>{{money(p.amount)}}</strong></article></div><div v-else class="small-empty">No payments have been recorded yet.</div></div></template></section></template>
